import pandas as pd

def find_unique_email_domains(emails: pd.DataFrame) -> pd.DataFrame:
    df = emails[emails['email'].str.endswith('.com')].copy()
    if df.empty:
        return pd.DataFrame(columns=['email_domain', 'count'])
    df['email_domain'] = df['email'].str.split('@').str[-1]
    res = df.groupby('email_domain').size().reset_index(name='count')
    return res.sort_values(by='email_domain')
